INSERT INTO `acao` VALUES (12,5,'01.001.01.846.0000.0095','REALIZAR O PAGAMENTO DE DÍVIDAS, INDENIZAÇÕES E SENTENÇAS JUDICIAIS','Preencher o quadro de pessoal permanente da Assembleia Legislativa por meio da realização de concurso público, nos termos da legislação vigente.','','Concurso público realizado','Un'),(13,5,'01.001.01.128.1006.2253','PROMOVER A CAPACITAÇÃO INSTITUCIONAL','Capacitar o Capital Humano oportunizando qualidade técnica de pessoal e estabelecendo condições para melhor servir à sociedade.','','Capacitações realizadas','Un'),(14,5,'01.001.01.126.1006.2405','POTENCIALIZAR A GESTÃO DE TECNOLOGIA DA INFORMAÇÃO E COMUNICAÇÃO','Tornar mais eficaz a gestão dos recursos de tecnologia da informação e comunicação, por meio do desenvolvimento, aquisição e implantação de novos equipamentos e sistemas, contratação de serviços e manutenção de contratos.','','Serviços Implementados','%'),(15,5,'01.001.01.122.1006.2406','FORTALECER A ESTRUTURA DO PODER LEGISLATIVO','Realizar despesas voltadas ao fortalecimento da estrutura da Assembleia Legislativa, exceto em tecnologia da informação e comunicação, envolvendo a contratação de serviços, consultoria, planejamento e execução de obras e instalações, aquisição de imóveis, equipamentos e materiais permanentes, e demais despesas relacionadas.','','Investimentos Realizados','%'),(16,5,'01.001.01.128.1006.2408','DESENVOLVER O PROGRAMA BOLSA ESTÁGIO','Oferecer Bolsa de estágio supervisionado para educandos que estejam frequentando o ensino regular em instituições de educação de ensino médio e superior, visando à preparação para o trabalho produtivo, por meio da prática em atividades específicas compatíveis com a sua formação e experiência.','','Bolsas Ofertadas','Un'),(17,6,'01.001.01.122.1020.2062','MANTER A ADMINISTRAÇÃO DA UNIDADE','Realizar despesas necessárias à manutenção e ao desenvolvimento das atividades da Assembleia Legislativa do Estado de Rondônia.','','Unidade Mantida','Un'),(18,6,'01.001.01.122.1020.2418','ASSEGURAR A REMUNERAÇÃO, BENEFÍCIOS E ENCARGOS SOCIAIS DA ÁREA ADMINISTRATIVA','Realizar o pagamento da remuneração mensal e 13º salário dos servidores da área administrativa da ALE-RO e outras eventuais despesas relacionadas, inclusive auxílios, indenizações por desligamentos e encargos sociais.','','Servidores Remunerado','Un'),(19,7,'01.001.01.031.2126.2409','PROMOVER A ATIVIDADE LEGISLATIVA E A PARTICIPAÇÃO CIDADÃ','Fornecer suporte para realização das atividades legislativas e promover a participação da sociedade e a ampliação do exercício da cidadania, por meio da realização de audiências públicas, instalação física de unidades de apoio, realização de ações itinerantes nos municípios e distritos do interior do Estado de Rondônia.','','Audiências públicas realizadas','Un'),(20,7,'01.001.01.031.2126.2416','PROMOVER A ATUAÇÃO DA ESCOLA DO LEGISLATIVO','Oferecer a profissionalização e capacitação a agentes políticos, servidores e comunidades, por meio de programas de formação, aperfeiçoamento e especialização, visando aprimorar a qualidade de suas atividades, ampliando sua formação em assuntos técnicos, administrativos e legislativos, bem como fornecer oportunidade de conhecimento da missão do Poder legislativo, dando-lhes condições de subsidiar a elaboração de proposições em geral.','','Cursos Ofertados','Un'),(21,7,'01.001.01.031.2126.2417','ASSEGURAR A REMUNERAÇÃO, BENEFÍCIOS E ENCARGOS SOCIAIS DA ÁREA FINALÍSTICA','Realizar o pagamento mensal e 13º salário da remuneração dos deputados e dos servidores que atuam predominantemente na área finalística da ALE-RO (gabinetes de deputados) e outras eventuais despesas relacionadas, inclusive auxílios e indenizações por desligamentos.','','Deputados e servidores da área finalística atendidos','Un'),(22,7,'01.001.01.131.2126.2665','REALIZAR AÇÕES DE COMUNICAÇÃO E PUBLICIDADE INSTITUCIONAL','Difundir nos meios de comunicação as atividades exercidas pela Assembleia Legislativa no cumprimento de suas atribuições constitucionais, por meio da contratação de serviços técnicos de publicidade e propaganda e da implantação e manutenção da Rádio-TV Legislativa, com divulgações de matérias de cunho legal, institucional, educacional e de utilidade pública.','','Campanhas Realizadas','Un'),(23,8,'02.001.01.122.0000.0163','CUMPRIR SENTENÇAS E/OU ACORDOS JUDICIAIS','Tem o objetivo de garantir a ampliação e manutenção de hardware e softwares, essenciais para o funcionamento eficiente do TCE-RO de maneira a contribuir com o fortalecimento e manutenção da capacidade operacional e laboral do TCE-RO.','','Ativos tangíveis e intangíveis de Tecnologia da Informação e','Comunicação modernos e atuais, para atender as demandas das áreas'),(24,8,'02.001.01.122.1010.1421','REFORMA E ADAPTAÇÃO DE IMÓVEIS DO TCE/RO','Reformar e ampliar imóveis do Tribunal de contas do Estado de Rondônia.','','Realização de adequação do prédio Anexo I, prédio Anexo III com','ampliação para atender a Escola de Contas, Arquivo e outras unidade do'),(25,8,'02.001.01.126.1010.2973','GESTÃO DOS RECURSOS DE TI E DESENVOLVIMENTO DE SOFTWARE','Modernizar serviços através do uso de software, ferramentas tecnológicas e serviços voltados ao suporte e manutenção de ferramentas de TI, de forma a permitir a otimização de recursos humanos e materiais, assim como, diminuição do tempo despendido em análises, fiscalizações e julgamentos, além de possibilitar a adequação a normas e frameworks, contribuindo para adoção de melhores práticas voltadas à inovação, modernização e segurança tecnológica do TCE-RO.','','Implantação/Continuidade do uso de softwares e serviços voltados para','evolução tecnológica do TCERO.'),(26,8,'02.001.01.122.1010.2981','GERIR AS ATIVIDADES DE NATUREZA ADMINISTRATIVAS','Assegurar o apoio administrativo para o exercício do controle externo das contas públicas e avaliação de políticas públicas.','','Cumprir o Plano Anual de Contratação - PAC.','%'),(27,9,'02.001.01.122.1011.2101','REMUNERAR O PESSOAL ATIVO E OBRIGAÇÕES PATRONAIS','Garantir o pagamento mensal da remuneração dos servidores e membros do TCE-RO e outras eventuais despesas relacionadas.','','Folha de pagamento regularmente processada.','Un'),(28,9,'02.001.01.128.1011.2542','GERIR AS AÇÕES DE CAPACITAÇÃO, APERFEIÇOAMENTO E INTEGRAÇÃO DO CAPITAL HUMANO','Proporcionar a qualificação de servidores e membros do Tribunal de Contas do Estado de Rondônia.','','Servidores capacitados.','%'),(29,9,'02.001.01.128.1011.2543','COORDENAR ESTÁGIOS E BOLSAS NA ADMINISTRAÇÃO DO TCE/RO','Proporcionar a realização de estágios aos alunos da rede pública estadual (nível médio) e instituições de ensino de nível superior no TCE-RO, bem como, fazer a gestão dos bolsistas que desenvolvem trabalhos técnicos especializados.','','Estágios e trabalhos técnicos realizados.','%'),(30,9,'02.001.01.122.1011.4073','INDENIZAR AUXÍLIOS AUTORIZADOS POR LEI AOS SERVIDORES E MEMBROS DO TCE/RO','Assegurar o deslocamento dos servidores no itinerário residência trabalho residência, auxiliando-os com indenização de auxilio transporte, e ainda, garantindo o pagamento dos auxílios saúde e alimentação, previstos em lei para todos os servidores componentes do quadro do TCE-RO.','','Indenização dos Auxílio Transporte, Auxílio Alimentação, Auxílio Saúde e','outros previstos em lei.'),(31,10,'02.001.09.272.1019.2854','REALIZAR PAGAMENTOS DE APOSENTADORIA E PENSÕES','Garantir o pagamento de aposentadoria aos inativos e pensão aos dependentes dos segurados do Tribunal de Contas.','','Pagamento realizado.','Un'),(32,11,'02.001.01.032.2146.2538','PROMOVER AÇÕES EDUCACIONAIS E DE COOPERAÇÃO TÉCNICA','Disseminar boas práticas que produzam resultados relevantes nas políticas públicas priorizadas no planejamento estratégico, visando a melhoria dos Índice de Governança em Políticas Educacionais e Índice de Governança em Políticas de Proteção das Unidades de Conservação.','','Capacitação dos Jurisdicionados.','Un'),(33,12,'02.001.01.032.2147.2523','CUMPRIR CONVÊNIOS INSTITUÍDOS COM ENTIDADES PRIVADAS SEM FINS LUCRATIVOS','Fortalecimento do sistema Tribunal de Contas, visando o aprimoramento das atividades exercidas nesta Corte de Contas.','','Cumprimento do Plano de Trabalho do Convênio.','%'),(34,12,'02.001.01.032.2147.2539','CONTROLE EXTERNO DA GESTÃO DE RECURSOS PÚBLICOS','Atuar por meio de ações de controle tempestivas para apreciar contas de governo, realizar o julgamento de contas e fiscalizações em volume de recursos relevantes.','','Apreciação de contas de governo e gestão tempestivamente.','Un'),(35,13,'02.011.01.122.1220.2640','CAPACITAR OS SERVIDORES DO TRIBUNAL DE CONTAS E JURISDICIONADOS','Criar condições técnicas e materiais que promovam o aperfeiçoamento e a capacitação do corpo funcional do TCE-RO e dos jurisdicionados, utilizando-se de metodologias e formas de aprimoramento das práticas administrativas. Tendo por objetivo treinar e capacitar no horizonte 2024 a 2027.','','Realizar cursos de capacitação profissional ao corpo funcional e seus','jurisdicionados, preparar técnicos instrutores do TCE-RO.'),(36,13,'02.011.01.122.1220.2977','GERIR AS ATIVIDADES DA ESCOLA DE CONTAS','Criar condições técnicas e materiais para implantação, estruturação e operacionalização da Escola Superior de Contas, visando a capacitação dos servidores do TCE-RO e jurisdicionados, com cursos de média e longa duração (stricto sensu e lato sensu), cursos técnicos e profissionais.','','Implantar, estruturar e operacionalizar a Escola de Contas do TCE-RO.','%'),(37,14,'03.001.02.122.1012.1484','PROMOVER AÇÕES DE SAÚDE PARA MAGISTRADOS (AS) E SERVIDORES (AS) DO PJRO','Promover ações de saúde para magistrados(as), servidores(as), dependentes, e estagiários(as) do Poder Judiciário do Estado de Rondônia (PJRO), visando melhorar na qualidade de vida no trabalho por meio de ações de atenção à saúde e contribuir para a redução do absenteísmo-doença.','','Atendimentos realizados','Un'),(38,14,'03.001.02.122.1012.1486','PROMOVER O BEM-ESTAR DE MAGISTRADOS (AS) E SERVIDORES (AS) DO PJRO','Promover ações que favoreçam a Política de Gestão de Pessoas com o fito de valorizar magistrados (as), servidores (as) e estagiários (as), e humanizar as relações, colaborando para o aumento do índice do Clima Organizacional e implantação do Programa de Qualidade de Vida no Trabalho.','','Atendimentos realizados','Un'),(39,14,'03.001.02.122.1012.2072','MANTER PROGRAMA DE ESTÁGIO PARA ESTUDANTES NO PODER JUDICIÁRIO DE RONDÔNIA','Dar suporte ao programa de estágio do Poder Judiciário de Rondônia para propiciar aos estudantes de nível médio e superior a oportunidade de aperfeiçoamento e complementação de ensino e aprendizagem, visando ao estímulo do desenvolvimento profissional.','','Estudantes Beneficiados','Un'),(40,14,'03.001.02.122.1012.2456','GERIR AÇÕES DE GESTÃO DE PESSOAS DO PJRO','Assegurar as ações de gestão de pessoas PJRO, relacionadas a saúde de magistrados/as e servidores/as, ao desenvolvimento de lideranças, ao acompanhamento de novos servidores em estágio probatório, bem como a manutenção da integridade física e mental dos colaboradores do PJRO.','','Unidade Mantida','Un'),(41,14,'03.001.02.122.1012.2481','ASSEGURAR A REMUNERAÇÃO, O PAGAMENTO DE BENEFÍCIOS E DESPESAS DE CARÁTER','Efetuar o pagamento de magistrados(as) do Poder Judiciário','','Pessoas Beneficiadas','Un'),(42,14,'03.001.02.122.1012.2482','ASSEGURAR A REMUNERAÇÃO, O PAGAMENTO DE BENEFÍCIOS E DESPESAS DE CARÁTER','Assegurar a Remuneração, o Pagamento de benefícios e despesas de caráter indenizatório os servidores do PJRO','','Pessoas Beneficiadas','Un'),(43,15,'03.001.02.122.1014.4078','GERIR ATIVIDADES DE SEGURANÇA PESSOAL E PATRIMONIAL DO PODER JUDICIÁRIO DO','Manter os serviços de vigilância eletrônica e de controle de acesso de pessoas e veículos, com a disponibilização de todos os componentes, tais como câmeras de circuito fechado de televisão (CFTV), sensores e alarmes, incluindo a atualização de softwares e manutenção preventiva e corretiva dos componentes disponibilizados; Serviços de Portaria terão como base o atendimento com presteza e periodicidade, observando a peculiaridade e frequência em cada caso, podendo para tanto atender, cadastrar, controlar, anunciar e encaminhar visitantes ao local desejado, prestar informações a magistrados, servidores, advogados e jurisdicionados, recepcionar e fazer ligações telefônicas, controlar e distribuir crachás de identificação, fazer registro em livros de ocorrência, auxiliar nos procedimentos de inspeção de segurança com o uso dos equipamentos necessários, monitorar por circuito interno de televisão, controlar a entrada e saída de veículos no estacionamento e prover equipamentos de controle de acesso que possibilitarão efetivo monitoramento do trânsito de pessoas armadas ou não nas dependências dos prédios, garantindo desenvolver as inspeções de segurança com discrição e agilidade imprimindo maior eficiência aos trabalhos da área de segurança, assim como, recursos humanos para realizar o monitorameno eletrônico no Centro Integrado de Monitoramento.','','Unidades atendidas','Un'),(44,15,'03.001.02.122.1014.4079','PROVER SEGURANÇA INSTITUCIONAL ATRAVÉS DO EMPREGO DE POLICIAIS MILITARES','Realizar o policiamento ostensivo nos prédios do Poder Judiciário, garantindo um ambiente seguro durante a prestação jurisdicional ao cidadão.','','Unidades Atendidas com segurança ostensiva e aproximada','Un'),(45,15,'03.001.02.122.1014.4080','DESENVOLVER E EXECUTAR ATIVIDADES VISANDO A SEGURANÇA CONTRA INCÊNDIO E PÂNICO','Manter regular todas as edificações dos fóruns do PJRO, com as devidas inspeções periódicas, e a instalação de equipamentos e materiais necessários, visando a execução das ações de prevenção, correção e de combate a incêndios; Desenvolver e supervisionar atividades visando a segurança contra incêndio e pânico das edificações do Poder Judiciário do Estado de Rondônia.','','Edificações atendidas','Un'),(46,16,'03.001.09.272.1019.2854','REALIZAR PAGAMENTOS DE APOSENTADORIA E PENSÕES','Pagamento de aposentadorias aos inativos, pensão aos dependentes dos segurados do Tribunal de Justiça do Estado.','','Pagamento realizado.','%'),(47,17,'03.001.02.122.2065.1192','CONSTRUIR NOVO FÓRUM DA COMARCA DE VILHENA','Construir edificação para abrigar Novo Fórum da Comarca de Vilhena/RO','','Fórum Construído','%'),(48,18,'03.011.02.846.0000.0236','REALIZAR DEVOLUÇÃO DE CUSTAS JUDICIAIS E OUTRAS OPERAÇÕES ESPECIAIS','Fortalecer a estratégia e os serviços de Tecnologia da Informação e Comunicação (TIC) no contexto do Poder Judiciário do Estado de Rondônia, visando aprimorar a governança, a eficiência e a qualidade dos serviços oferecidos, bem como impulsionar a inovação tecnológica no ambiente judiciário.','','Estratégia e serviços de TIC executados','%'),(49,18,'03.011.02.126.1013.2189','MANTER A TECNOLOGIA DA INFORMAÇÃO E COMUNICAÇÃO DO PJRO','Garantir a efetiva gestão, manutenção e provisão de serviços de Tecnologia da Informação e Comunicação (TIC) no âmbito do Poder Judiciário do Estado de Rondônia, visando assegurar a disponibilidade, segurança e desempenho adequados dos sistemas, infraestrutura e recursos tecnológicos utilizados, a fim de suportar as atividades judiciais e administrativas de forma eficiente.','','Contratos de Soluções de TIC Realizados','Un'),(50,18,'03.011.02.126.1013.4077','GERIR AÇÕES DE SEGURANÇA CIBERNÉTICA','O objetivo dessa ação é fortalecer a segurança da informação e cibernética no âmbito do Poder Judiciário do Estado de Rondônia, visando mitigar os riscos de incidentes e proteger os sistemas, informações e dados sensíveis contra ameaças e ataques cibernéticos, assegurando a confidencialidade, integridade e disponibilidade das informações institucionais.','','Contratos de segurança cibernética realizados','Un'),(51,19,'03.011.02.122.1017.2451','MANTER AS ATIVIDADES DA ESCOLA DA MAGISTRATURA DE RONDÔNIA','Assegurar a manutenção das atividades administrativas da EMERON, visando a execução das iniciativas de formação e aperfeiçoamento de magistrados e servidores para alcance da visão do PJRO e melhoria dos serviços judiciais.','','Unidade Mantida','Un'),(52,19,'03.011.02.128.1017.2478','PROMOVER A FORMAÇÃO CONTINUADA DE MAGISTRADOS (AS) E SERVIDORES (AS) DO PODER','Promover a formação, extensão, o aperfeiçoamento, a valorização, a atualização da função pública de magistrados e servidores do Poder Judiciário e da administração pública do Estado de Rondônia, vinculadas às competências, aos objetivos e às metas estratégicos do Poder Judiciário do Estado de Rondônia.','','Magistrados(as) e Servidores(as) capacitados em ações educacionais','ofertadas pela Emeron'),(53,19,'03.011.02.128.1017.4081','PROMOVER CURSOS DE PÓS-GRADUAÇÃO E FOMENTO A PESQUISA E EXTENSÃO','Promover formação especializada de magistrados(as) e servidores(as) do Poder Judiciário, assim como demais interessados da sociedade, promovendo ou financiando cursos de Pós-graduação lato sensu e stricto sensu, fomentando atividades de pesquisa, publicação e extensão acadêmica, aprimorando a atuação do Poder Judiciário a partir da formação de profissionais capacitados.','','Pessoas especializadas em nível de Pós-graduação em cursos ofertados','pela Emeron.'),(54,20,'03.011.02.061.1018.1642','APRIMORAR OS PROCESSOS DOS MÉTODOS CONSENSUAIS DE SOLUÇÃO DE CONFLITOS','Promover o aperfeiçoamento dos processos e das rotinas visando aprimorar procedimentos de métodos consensuais de solução de conflitos e melhorias para resolver problemas atinentes à dificuldade na tomada de decisões ágeis e eficientes, além da sobrecarga na programação das atividades das unidades.','','Processos e Rotinas Remodeladas','Un'),(55,20,'03.011.02.061.1018.4138','APERFEIÇOAR A GESTÃO E OS PROCEDIMENTOS DAS UNIDADES JUDICIÁRIAS','Aperfeiçoar o atendimento à demanda judicial, por meio de iniciativas que modernizam e impulsionam os serviços, contribuindo para a eficiência e efetividade da Justiça ao jurisdicionado.','','Soluções Judiciais Implementadas','Un'),(56,20,'03.011.02.061.1018.4139','FORTALECER A RELAÇÃO DO JUDICIÁRIO COM A SOCIEDADE','Implementar medidas e iniciativas que promovam a transparência institucional, a comunicação efetiva com os cidadãos e a disseminação de informações sobre o funcionamento do Poder Judiciário.','','Iniciativas realizadas','Un'),(57,20,'03.011.02.061.1018.4140','REALIZAR CORREIÇÕES E INSPEÇÕES NAS UNIDADES JUDICIAIS DO 1° GRAU','Realizar correições, inspeções, visitas técnicas e orientações com vista ao aperfeiçoamento dos serviços judiciais do 1° grau, promovendo a eficiência, a qualidade e a celeridade da prestação jurisdicional.','','Unidades judiciais correicionadas, inspecionadas e orientadas','Un'),(58,20,'03.011.02.061.1018.4141','FORTALECER POLÍTICAS JUDICIÁRIAS PARA A INFÂNCIA E JUVENTUDE','Concerne à adoção de estratégias de comunicação e de procedimentos objetivos, ágeis e em linguagem de fácil compreensão, visando à transparência e ao fortalecimento do Poder Judiciário de Rondônia como instituição garantidora dos direitos. Abrange a atuação interinstitucional integrada e sistêmica, com iniciativas na área da Infância e da Juventude, que envolvam instituições do Estado, da sociedade civil e de toda a coletividade.','','Intervenções no âmbito da Infância e Juventude realizadas','Un'),(59,20,'03.011.02.061.1018.4142','MONITORAR E FISCALIZAR ESTABELECIMENTOS PENAIS E UNIDADES SOCIOEDUCATIVAS','Promover o monitoramento e a fiscalização efetiva dos estabelecimentos penais e unidades Socioeducativas, com o objetivo de garantir o cumprimento dos direitos dos detentos e adolescentes em cumprimento de medida socioeducativa, assegurando condições adequadas de encarceramento e internação e contribuir para a segurança e ressocialização dos indivíduos privados de liberdade.','','Inspeções e Fiscalizações Realizadas','Un'),(60,21,'03.011.02.061.1031.1641','REALIZAR INICIATIVAS PARA AUXILIAR NA POLÍTICA DE REGULARIZAÇÃO FUNDIÁRIA NO','Contribuir para a concretização da regularização fundiária urbana, com objetivo de defender o direito à moradia e à cidadania, prevenir litígios e reduzir demandas possessórias e de propriedades, bem como, conscientizar os gestores públicos municipais sobre a obrigatoriedade de regularizar os núcleos urbanos em situação de informalidade.','','Iniciativas voltadas à regularização fundiária realizadas','Un'),(61,21,'03.011.02.122.1031.4135','COMPENSAR ATOS GRATUITOS, SELOS ISENTOS E COMPLEMENTAÇÃO DA RENDA MÍNIMA ÀS','Compensar atos gratuitos e selos isentos, bem como conceder o benefício de complementação de renda mínima, em razão de competência decorrente de lei, vislumbrando garantir os direitos da cidadania estabelecidos constitucionalmente, bem como o de assegurar subsistência àquelas serventias deficitárias que praticam atos no âmbito do registro civil das pessoas naturais, em cumprimento a Lei Estadual n. 918/2000 e suas alterações e Resolução n. 005/2011-PR.','','Serventias Compensadas','Un'),(62,21,'03.011.02.061.1031.4136','GERIR SERVIÇOS EXTRAJUDICIAIS','Promover a excelência na administração dos serviços extrajudiciais, garantindo a eficiência, a segurança jurídica, a acessibilidade e efetividade desses serviços em benefício da sociedade por meio do aperfeiçoamento da gestão, da realização de correições, do provimento das serventias vagas e capacitação e orientação dos profissionais.','','Serventias Extrajudiciais Atendidas','Un'),(63,22,'03.011.02.122.2065.1480','CONSTRUIR NOVO FÓRUM DE ROLIM DE MOURA/RO','Construção de unidade predial para abrigo do Novo Fórum de Rolim de Moura/RO, visando atender a demanda de processos judiciais e oferecer espaço adequado para prestação jurisdicional e recepção do jurisdicionado, observando as normas atinentes à execução da obra, à acessibilidade, à segurança, meio ambiente e aos princípios da Administração Pública. O projeto prevê a construção de um prédio moderno e funcional, com fachada e espaço aberto de praça/paisagismo e com a reutilização de águas pluviais e cobertura com possibilidade de instalação de placas solares. A edificação possui 3.371,65 metros quadrados, em um terreno de 3.672,82 m2. Obra iniciada em 09/08/2022 com previsão de conclusão em 18/06/2024 (660 dias).','','Fórum Construído','%'),(64,22,'03.011.02.122.2065.1507','CONSTRUIR FÓRUNS DIGITAIS','Construção de edificação para abrigar Fóruns Digitais que oferecem serviços judiciais à população, de forma eletrônica e remota, em parceria com as Prefeituras, MP, DPE, TRT, TRF, TRE, MPT, MPF e outras instituições públicas para assegurar direitos e cidadania a quem não pode se deslocar até a sede da Comarca.','','Fóruns Digitais Construídos','Un'),(65,22,'03.011.02.122.2065.1508','CONSTRUIR NOVO FÓRUM DE COLORADO DO OESTE/RO','Construção de unidade predial para abrigo do Novo Fórum de Colorado do Oeste/RO visando o atendimento de demandas de processos judiciais e o oferecimento de espaço adequado para prestação jurisdicional e recepção do jurisdicionado Deverão ser observadas as normas atinentes à execução da obra, à acessibilidade, à segurança, meio ambiente e aos princípios da Administração Pública. O projeto prevê a construção de um prédio moderno e funcional baseado nas recentes concepções arquitetônicas das obras de Rolim de Moura/RO e Vilhena/RO, incluindo a utilização da metodologia de Light Steel Frame - LSF.','','Fórum Construído','%'),(66,22,'03.011.02.122.2065.1509','CONSTRUIR NOVO FÓRUM DE NOVA MAMORÉ/RO','Construção de unidade predial para abrigo do Novo Fórum de Nova Mamoré/RO visando o atendimento de demandas de processos judiciais e o oferecimento de espaço adequado para prestação jurisdicional e recepção do jurisdicionado Deverão ser observadas as normas atinentes à execução da obra, à acessibilidade, à segurança, meio ambiente e aos princípios da Administração Pública. O projeto prevê a construção de um prédio moderno e funcional baseado nas recentes concepções arquitetônicas das obras de Rolim de Moura/RO e Vilhena/RO, incluindo a utilização da metodologia de Light Steel Frame - LSF.','','Fórum Construído','%'),(67,22,'03.011.02.122.2065.1518','DOTAR O FÓRUM GERAL DA COMARCA DE PORTO VELHO COM INSTALAÇÕES FÍSICAS','Prover o Fórum Geral da Comarca de Porto Velho com um imóvel adequado e seguro para a realização da prestação jurisdicional, garantindo o acesso à justiça de forma efetiva e eficiente','','Imóvel construído/adquirido.','Un'),(68,22,'03.011.02.122.2065.1628','REFORMAR O EDIFÍCIO SEDE','Revitalizar os ambientes de representação e recepção do Edifício Sede com o propósito de melhorar a funcionalidade, a segurança e a sustentabilidade das edificações, ao mesmo tempo em que se promove um ambiente mais acolhedor e acessível para Magistrados(as), Servidores(as) e o público em geral.','','Edifício Sede Reformado','%'),(69,22,'03.011.02.122.2065.1629','REFORMAR O ANEXO ADMINISTRATIVO','Reforma do anexo administrativo a fim de oferecer espaço adequado para a realização das atividades da unidade, observando as normas atinentes à execução da obra, à acessibilidade, à segurança, ao meio ambiente e aos princípios da Administração Pública.','','Anexo Administrativo reformado.','%'),(70,22,'03.011.02.122.2065.1630','REFORMAR O FÓRUM DA COMARCA DE GUAJARÁ MIRIM/RO','Reforma da unidade predial que abriga o Fórum de Guajará Mirim/RO visando o atendimento de demanda de processos judiciais e o oferecimento de espaço adequado para prestação jurisdicional e recepção do jurisdicionado. Deverão ser observadas as normas relativas à execução da obra, à acessibilidade, à segurança, ao meio ambiente e aos princípios da Administração Pública.','','Fórum reformado.','%'),(71,22,'03.011.02.122.2065.1631','REFORMAR O FÓRUM DA COMARCA DE MACHADINHO DO OESTE/RO','Reforma da unidade predial que abriga o Fórum de Machadinho do Oeste/RO visando o atendimento de demanda de processos judiciais e o oferecimento de espaço adequado para prestação jurisdicional e recepção do jurisdicionado. Deverão ser observadas as normas relativas à execução da obra, à acessibilidade, à segurança, ao meio ambiente e aos princípios da Administração Pública.','','Fórum Reformado','%'),(72,22,'03.011.02.122.2065.1632','REFORMAR E AMPLIAR O CENTRO DE APOIO LOGÍSTICO','Reforma da unidade predial que abriga o Centro de Apoio Logístico visando o oferecimento de espaço adequado para realização de atividades administrativas no local. Deverão ser observadas as normas relativas à execução da obra, à acessibilidade, à segurança, ao meio ambiente e aos princípios da Administração Pública.','','Centro De Apoio Logístico Reformado E Ampliado','%'),(73,22,'03.011.02.122.2065.1633','REVITALIZAR AS INSTALAÇÕES DO PODER JUDICIÁRIO DE RONDÔNIA','Revitalizar as instalações do Poder Judiciário do Estado de Rondônia (PJRO) em geral, com o propósito de melhorar a funcionalidade, a segurança e a sustentabilidade das edificações, ao mesmo tempo em que se promove um ambiente mais acolhedor e acessível para Magistrados(as), Servidores(as) e o público em geral.','','Edifícios Reformados','Un'),(74,23,'03.011.02.122.2073.2449','MANTER AS ATIVIDADES ADMINISTRATIVAS DO PJRO','Viabilizar a manutenção das unidades administrativas e judiciárias do PJRO.','','Comarcas Mantidas','Un'),(75,24,'03.011.02.061.2185.4137','EFETIVAR OS MÉTODOS CONSENSUAIS DE CONFLITO','Realizar iniciativas para efetivar os Métodos Consensuais de Solução de Conflitos no PJRO.','','',''),(76,25,'03.011.02.061.2186.1643','ENFRENTAR A VIOLÊNCIA CONTRA A MULHER','Prevenir as violências contra as mulheres; conceder acesso e garantia de direitos e assistir as vítimas; enfrentar e combater as violências e fortalecer e gerir as iniciativas, do PJRO, de combate às violências contra as mulheres.','','Mulheres Atendidas','Un'),(77,26,'11.003.04.846.0000.0023','REALIZAR PAGAMENTO DE ADVOGADOS DATIVOS, HONORÁRIOS EVENTUAIS, RPV E OUTROS','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(78,26,'11.003.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(79,26,'11.003.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(80,26,'11.003.04.123.1015.4103','MANTER A MÃO DE OBRA REEDUCANDA','Viabilizar o pagamento de mão de obra de reeducandos do sistema prisional do Estado de Rondônia, por meio de descentralização realizada pelas unidades do estado para o Fundo Penitenciário.','','Pagamentos realizados para reeducandos','Un'),(81,27,'11.003.04.122.2085.4160','MELHORAR A ESTRUTURA FÍSICA DA PGE/RO','Prover a Procuradoria Geral do Estado (PGE) com infraestrutura física, tecnológica e outros bens permanentes necessários para o desempenho de sua função singular de representar e defender o Estado de Rondônia. Dessa forma, a PGE poderá cumprir sua missão institucional, contribuindo para a melhoria dos serviços prestados à população. Visando aprimorar as condições de trabalho dos procuradores e demais servidores, provendo os recursos materiais e tecnológicos adequados para uma atuação eficiente da instituição no cumprimento de seu papel.','','Melhorias Realizada','Un'),(82,28,'11.003.04.122.2155.2604','PROMOVER A MELHORIA DA GESTÃO DE COBRANÇA DA DÍVIDA ATIVA','Implementar um conjunto de ações e práticas que permitam otimizar o processo de cobrança da dívida ativa, tornando-o mais ágil, assertivo e alinhado às necessidades do Estado de Rondônia.','','Consultoria Realizada.','Un'),(83,28,'11.003.04.122.2155.2605','MODERNIZAÇÃO TECNOLÓGICA DA GESTÃO DE COBRANÇA DA DÍVIDA ATIVA','Com o desenvolvimento de sistemas de informação e uso de inteligência artificial realizar a gestão da dívida ativa com excelência.','','Sistema de informação voltado a gestão da dívida ativa.','Un'),(84,29,'11.004.04.122.1015.2087','ASSEGURAR A MANUTENÇÃO ADMINISTRATIVA DA UNIDADE','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(85,29,'11.004.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(86,29,'11.004.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(87,29,'11.004.04.122.1015.4103','MANTER A MÃO DE OBRA REEDUCANDA','Viabilizar o pagamento de mão de obra de reeducandos do sistema prisional do Estado de Rondônia, por meio de descentralização realizada pelas unidades do estado para o Fundo Penitenciário.','','Pagamentos realizados para reeducandos','Un'),(88,30,'11.004.23.695.2108.1215','PROMOVER A OFERTA DE TURISMO','Promover a oferta de Turismo, através de investimentos na estruturação e custeio de atrativos, visando melhores produtos. Desenvolver o Turismo do estado de acordo com princípios orientadores estabelecidos na Política Estadual de Turismo com o Plano Estadual de Turismo elaborado. Fomentar os seguimentos turísticos em diversas modalidades, realizando ações de infraestrutura e identificação dos principais pontos turísticos do Estado, com Placas de sinalização, ampliações e reformas, construções.','','Municípios com oferta de Turismo Promovida.','Un'),(89,30,'11.004.23.695.2108.2194','PROMOVER ATIVIDADES DE APOIO E DIVULGAÇÃO DO TURISMO DE RO','Promover ações/atividades de apoio e divulgação do Turismo de Rondônia.','','Ações de divulgação promovidas.','Un'),(90,30,'11.004.23.122.2108.4126','MANTER CENTROS TURÍSTICOS','Garantir o funcionamento e manutenção das atividades em centros e pontos turísticos de Estado.','','Centros turísticos mantidos.','Un'),(91,31,'11.005.04.122.1015.2087','ASSEGURAR A MANUTENÇÃO ADMINISTRATIVA DA UNIDADE','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(92,31,'11.005.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(93,31,'11.005.04.122.1015.2096','FORMAR, QUALIFICAR, TREINAR E CAPACITAR RECURSOS HUMANOS.','Melhorar a qualidade dos serviços prestados pela instituição por meio da formação e melhoria contínua de seus servidores.','','Servidor capacitado e treinado.','Un'),(94,31,'11.005.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(95,31,'11.005.04.122.1015.4000','PROMOVER AÇÕES PREVENTIVAS DE SAÚDE OCUPACIONAL E QUALIDADE DE VIDA NO','Promover saúde ocupacional e qualidade de vida dos servidores no trabalho.','','Pessoas atendidas','Un'),(96,32,'11.005.04.122.2190.2359','DESENVOLVER INOVAÇÕES TECNOLÓGICAS','Impulsionar a modernização do Órgão de Controle Interno do Poder Executivo Estadual, por meio da aquisição de ativos tecnológicos e serviços de tecnologia necessárias para fortalecer a atuação eficiente no Sistema de Controle Interno Central.','','Ativos e Serviços de Tecnologia da Informação.','Un'),(97,32,'11.005.04.122.2190.2361','APERFEIÇOAMENTO ÀS ATIVIDADES DA AUDITORIA INTERNA GOVERNAMENTAL, FOMENTO À','Realizar ações que visem a evolução da capacidade de auditoria interna governamental, bem como o aperfeiçoamento das atividades de controladoria, responsabilização de pessoa jurídica, fomento à implementação da gestão de riscos, transparência e integridade na unidades do Poder Executivo do Estado.','','Servidores atendidos.','Un'),(98,32,'11.005.04.122.2190.4159','GESTÃO PARTICIPATIVA ENTRE A COMUNIDADE ESCOLAR PÚBLICA ESTADUAL E A','Implantar ações que visem a prática cidadã na comunidade escolar pública estadual através do Projeto Estudante Auditor, com escolas públicas de ensino fundamental e médio (do sexto ano do ensino fundamental ao segundo do ensino médio) tendo como público-alvo direto estudantes, professores/profissionais de educação e gestores de escolas públicas e de maneira indireta pais ou responsáveis e os envolvidos no ambiente da comunidade escolar.','','',''),(99,33,'11.006.04.122.1015.1519','REALIZAÇÃO DE CONCURSO PÚBLICO E PROCESSO SELETIVO','Realizar concurso público e/ou processo seletivo para provimento de cargos públicos do quadro de pessoal da Instituição.','','Concurso realizado / Processo seletivo realizado','Un'),(100,33,'11.006.04.122.1015.2087','ASSEGURAR A MANUTENÇÃO ADMINISTRATIVA DA UNIDADE','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(101,33,'11.006.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(102,33,'11.006.04.122.1015.2096','FORMAR, QUALIFICAR, TREINAR E CAPACITAR RECURSOS HUMANOS.','Melhorar a qualidade dos serviços prestados pela instituição por meio da formação e melhoria contínua de seus servidores.','','Servidor capacitado e treinado.','Un'),(103,33,'11.006.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(104,34,'11.006.11.334.2000.2009','PROMOVER A INTERMEDIAÇÃO DE MÃO DE OBRA','Assegurar recursos para custeio financeiro, administrativo e logístico necessários ao suporte da execução das ações inerentes ao cadastramento, encaminhamento dos trabalhadores ao mercado de trabalho, cadastramento das vagas ofertadas pelo Empregador ao SINE, recepção ao benefício Seguro Desemprego, orientações quanto a emissão de Carteiras de Trabalho, orientações e esclarecimentos de dúvidas quanto aos serviços oferecidos pelo SINE.','','Apoio administrativo e logístico para execução das atividades finalísticas','executadas pelo SINE (COTER)'),(105,34,'11.006.19.573.2000.4144','PROMOVER A MODERNIZAÇÃO E DESENVOLVIMENTO DA ECONOMIA POR MEIO DA CIÊNCIA E','Promover e fortalecer a cultura da inovação com criação de empresas de base tecnológicas do Estado de Rondônia, incentivando o desenvolvimento de produtos e processos inovadores para o alcance de uma maior dinâmica tecnológica de capacitação, de competitividade, formação contínua e o desenvolvimento econômico sustentável, industrial, tecnológico e o desenvolvimento de produtos e processos inovadores em Empresas e Entidades de Direito Privado. Estimulando à atividade de inovação nas Instituições Científicas, Tecnológica e de Inovação, a constituição e a instalação de centros de pesquisa, parques, polos tecnológicos, arranjos produtivos locais e clusters tecnológicos.','','Ambientes/habitats de inovação, Número de Pré-Incubados e startups.','Un'),(106,34,'11.006.23.691.2000.4145','PROMOVER A COMPETITIVIDADE DAS CADEIAS PRODUTIVAS REGIONAIS','Assegurar recursos para a realização de incentivo de natureza financeira às micro, pequenas e médias empresas, aos microempreendedores e empreendedores cadastrados no Cadastro Único para Programas Sociais - CadÚnico, bem como o desenvolvimento às cadeias produtivas regionais, aumentar a competitividade e incentivar o empreendedorismo; Programa de Apoio as Micro e Pequenas Empresas e Empreendedores de Pequenos Negócios.','','Fomento as Micro, Pequenas e Médias empresas e empreendedores de','pequenos negócios através do PROAMPE e feiras de'),(107,34,'11.006.23.122.2000.4146','PROMOVER A ATRAÇÃO DE INVESTIMENTOS','Atrair investimentos nacionais ou estrangeiros, promovendo e estimulando a expansão de empresas instaladas no Estado de Rondônia, auxiliando Municípios e seus ambientes de inovação ao investidor no desenvolvimento de novos negócios e novos mercados.','','Aumento de exportações, comércio, serviços e Empresas Instaladas','Un'),(108,34,'11.006.23.692.2000.4148','GERAR E PRODUZIR GEOINTELIGÊNCIA DE DADOS ECONÔMICOS','Subsidiar tomada de decisões de Gestores Públicos e Privados, incluso o auxílio na atração de Investimentos, bem como fornecimento de dados e informações a População.','','Relatórios, Estudos e Painéis em Sítios Eletrônicos (Infraestrutura de','dados espaciais)'),(109,35,'11.006.14.422.2072.2661','GARANTIR OS DIREITOS DO CONSUMIDOR','Prover recursos para as ações de proteção, segurança, educação, desenvolvimento de programas e políticas de conscientização dos direitos e deveres dos atores da relação de consumo intuindo garantir o equilíbrio do mercado de consumo de forma sustentável, modernização e estruturação do Procon Rondônia.','','Estabelecimento Fiscalizado, Atendimento realizado nas Unidades Procon','Rondônia e Acessos ao pacote de serviços.'),(110,36,'11.006.23.130.2142.1505','MODELAGEM PARA CONCESSÃO DE SERVIÇOS PÚBLICOS.','Definir a viabilidade econômico-financeira objetivando a atratividade para concessão de serviços públicos.','','Resultado dos Estudos de Viabilidade de pactuação de PPP no âmbito do','Estado de Rondônia.'),(111,37,'11.006.23.122.2187.4150','REALIZAR APORTE DE CAPITAL','Realizar aporte de capital e subvenções econômicas à Companhia de Mineração de Rondônia (CMR), à Sociedade de Portos e Hidrovias do Estado de Rondônia - SOPH, à Companhia de Águas de Rondônia (CAERD) e à Companhia de Gás do Estado de Rondônia (RONGÁS)','','Realizar aporte de capital e subvenção econômica','%'),(112,37,'11.006.23.122.2187.4151','ASSEGURAR O MONITORAMENTO, EVOLUÇÃO E GESTÃO DAS ESTATAIS','Assegurar o aperfeiçoamento da atuação do Estado enquanto acionista controlador das Estatais, com o objetivo de fortalecer a governança nas empresas e promover a articulação e integração das políticas governamentais, bem como, promover, a gestão das informações para o Governo do Estado de Rondônia.','','Fortalecimento da governança e integração das políticas governamentais','Un'),(113,38,'11.007.04.122.1015.1490','REALIZAR PAGAMENTOS DE PROFISSIONAIS TEMPORÁRIOS','Viabilizar remuneração de profissionais temporários e pagamento de outros benefícios/auxílios e encargos sociais .','','Profissional remunerado.','Un'),(114,38,'11.007.04.122.1015.2087','ASSEGURAR A MANUTENÇÃO ADMINISTRATIVA DA UNIDADE','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(115,38,'11.007.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(116,38,'11.007.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(117,39,'11.007.04.126.2074.1000','EXPANSÃO DA INFOVIA','O projeto Expansão da INFOVIA é necessário para instrumentalizar o Governo do Estado com uma rede de voz e dados integrada a serviços de modernização da gestão pública e fomentar o desenvolvimento econômico e social em diversas áreas de Rondônia.','','Fornecer acesso à INFOVIA, preferencialmente, para os municípios do','eixo da BR-364.'),(118,39,'11.007.04.126.2074.2283','GERENCIAR AS ATIVIDADES DE AQUISIÇÃO, MANUTENÇÃO, DESENVOLVIMENTO E','Subsidiar e aprimorar o processo de gestão, adequando-o às particularidades, características, demandas e variáveis do Governo, por meio de sistemas que promovam a integração, automação e gestão de processos e a eficiência em âmbito estadual.','','Garantir o pleno funcionamento dos sistemas computacionais utilizados','pelos órgãos públicos do Estado.'),(119,39,'11.007.04.126.2074.2285','PROVER, ADMINISTRAR E MANTER A INFRAESTRUTURA DE TECNOLOGIA DA INFORMAÇÃO E','Promover a gestão de recursos de TIC (Tecnologia da Informação e Comunicação) objetivando proporcionar a infraestrutura necessária para a melhoria dos serviços prestados ao cidadão.','','Infraestrutura de rede de comunicação de dados e tecnologia da','informação mantida e adequada às necessidades governamentais.'),(120,40,'11.008.04.122.1015.2087','ASSEGURAR A MANUTENÇÃO ADMINISTRATIVA DA UNIDADE','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(121,40,'11.008.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(122,40,'11.008.04.128.1015.2096','FORMAR, QUALIFICAR, TREINAR E CAPACITAR RECURSOS HUMANOS.','Melhorar a qualidade dos serviços prestados pela instituição por meio da formação e melhoria contínua de seus servidores.','','Servidor capacitado e treinado.','Un'),(123,40,'11.008.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(124,40,'11.008.04.122.1015.4103','MANTER A MÃO DE OBRA REEDUCANDA','Viabilizar o pagamento de mão de obra de reeducandos do sistema prisional do Estado de Rondônia, por meio de descentralização realizada pelas unidades do estado para o Fundo Penitenciário.','','Pagamentos realizados para reeducandos','Un'),(125,41,'11.008.04.122.2058.1523','REALIZAR PROJETO PARA COMPRAS COMPARTILHADAS DO PODER EXECUTIVO','Viabilizar a elaboração de Projeto Técnico que conterá estudo sobre o resultado da possível implantação e idealização das compras compartilhadas em âmbito estadual de Rondônia.','','Estudos realizados/promovidos','Un'),(126,41,'11.008.04.122.2058.2570','APRIMORAR A GESTÃO NOS PROCESSOS LICITATÓRIOS','Ofertar capacitação às unidades da administração pública do estado de Rondônia organizadas em Oficinas por semelhança das atividades finalísticas das unidades, no intuíto de promover agilidade e eficiências nas entregas dos bens e serviços a sociedade.','','Oficinas realizadas com certificação aos servidores','Un'),(127,42,'11.009.04.122.1015.2087','ASSEGURAR A MANUTENÇÃO ADMINISTRATIVA DA UNIDADE','Prover os meios administrativos para a gestão dos programas e ações da instituição e para o funcionamento da unidade.','','Unidade Mantida.','Un'),(128,42,'11.009.04.122.1015.2091','ATENDER A SERVIDORES COM AUXÍLIOS','Viabilizar remuneração de servidores com auxílios','','Servidor remunerado','Un'),(129,42,'11.009.04.122.1015.2174','ASSEGURAR MANUTENÇÃO DO PALÁCIO RIO MADEIRA E ANEXOS','Garantir recursos para disponibilizar aos servidores e cidadãos uma estrutura predial do Palácio Rio Madeira - PRM e Anexos adequada.','','Manutenção do Palácio Rio Madeira e anexos assegurada','%'),(130,42,'11.009.04.122.1015.2234','ASSEGURAR A REMUNERAÇÃO DE PESSOAL ATIVO E ENCARGOS SOCIAIS','Viabilizar remuneração de pessoal ativo e encargos sociais, bem como a contribuição do Estado para o custeio dos regime de previdência próprio e complementar.','','Servidor remunerado.','Un'),(131,42,'11.009.04.123.1015.4103','MANTER A MÃO DE OBRA REEDUCANDA','Viabilizar o pagamento de mão de obra de reeducandos do sistema prisional do Estado de Rondônia, por meio de descentralização realizada pelas unidades do estado para o Fundo Penitenciário.','','Pagamentos realizados para reeducandos','Un'),(132,43,'11.009.04.123.2041.2497','CONSÓRCIO INTERESTADUAL DE DESENVOLVIMENTO SUSTENTÁVEL DA AMAZÔNIA LEGAL?','Fomentar o desenvolvimento econômico e social da Amazônia Legal, de maneira harmônica e sustentável, através da participação do Estado no consórcio.','','Consórcio Mantido','%'),(133,